16	func TestValidNamesAccepted(t *testing.T) {
17		root := New("tool", "root", nil, noop)
18		cases := []struct {
19			name    string
20			aliases []string
21		}{
22			{"a", nil},
23			{"A1-_", []string{"x", "Y", "0", "_ok", "a-b_c9"}},
24			{"serve", []string{"srv", "S"}},
25			{"_", []string{"9", "a_B-C"}},
26		}
27		for _, c := range cases {
28			if err := root.Add(New(c.name, "", c.aliases, noop)); err != nil {
29				t.Errorf("Add(%q, %v) unexpected error: %v", c.name, c.aliases, err)
30			}
31		}
32	}
