34	func TestInvalidPrimaryNamesRejected(t *testing.T) {
35		bad := []string{
36			"",      // empty
37			"-x",    // leading hyphen
38			"-",     // only a hyphen
39			"a b",   // space
40			"a.b",   // punctuation
41			"a/b",   // slash
42			"日本",    // non-ASCII
43			"café",  // non-ASCII byte
44			"a\nb",  // control character
45			"a--b ", // trailing space
46		}
47		for _, name := range bad {
48			root := New("tool", "", nil, noop)
49			err := root.Add(New(name, "", nil, noop))
50			if !errors.Is(err, ErrInvalidName) {
51				t.Errorf("Add(%q) error = %v, want errors.Is ErrInvalidName", name, err)
52			}
53			var ne *NameError
54			if !errors.As(err, &ne) || ne.Name != name {
55				t.Errorf("Add(%q) error does not carry *NameError{Name: %q}: %v", name, name, err)
56			}
57		}
58	}
