94	func TestSiblingNameConflicts(t *testing.T) {
95		root := New("tool", "", nil, noop)
96		if err := root.Add(New("serve", "", []string{"s"}, noop)); err != nil {
97			t.Fatal(err)
98		}
99		cases := []struct {
100			label   string
101			name    string
102			aliases []string
103		}{
104			{"primary repeats primary", "serve", nil},
105			{"primary repeats alias", "s", nil},
106			{"alias repeats primary", "other", []string{"serve"}},
107			{"alias repeats alias", "other", []string{"s"}},
108			{"case-sensitive distinct is allowed", "SERVE", []string{"S"}},
109		}
110		for i, c := range cases {
111			err := root.Add(New(c.name, "", c.aliases, noop))
112			if i == len(cases)-1 {
113				if err != nil {
114					t.Fatalf("%s: unexpected error %v", c.label, err)
115				}
116				continue
117			}
118			if !errors.Is(err, ErrNameConflict) {
119				t.Errorf("%s: error = %v, want ErrNameConflict", c.label, err)
120			}
121		}
122	}
