148	func TestFailedAddLeavesTreeUntouched(t *testing.T) {
149		root := New("tool", "", nil, noop)
150		if err := root.Add(New("keep", "", nil, noop)); err != nil {
151			t.Fatal(err)
152		}
153		before := len(root.children)
154		for _, child := range []*Node{
155			nil,
156			New("keep", "", nil, noop), // conflicts
157			New("bad!", "", nil, noop), // invalid
158			New("x", "", []string{"x"}, noop),
159		} {
160			if err := root.Add(child); err == nil {
161				t.Fatalf("Add(%v) unexpectedly succeeded", child)
162			}
163		}
164		if len(root.children) != before {
165			t.Fatalf("children count changed from %d to %d after failed adds", before, len(root.children))
166		}
167		// A valid add after failures still works, proving no partial mutation.
168		if err := root.Add(New("after", "", nil, noop)); err != nil {
169			t.Fatalf("valid Add after failures: %v", err)
170		}
171	}
