190	func TestAliasesCopied(t *testing.T) {
191		src := []string{"a", "b"}
192		n := New("n", "desc", src, nil)
193		src[0] = "mutated"
194		if got := n.Aliases(); !reflect.DeepEqual(got, []string{"a", "b"}) {
195			t.Fatalf("constructor did not copy aliases: %v", got)
196		}
197		out := n.Aliases()
198		out[0] = "mutated"
199		if got := n.Aliases(); !reflect.DeepEqual(got, []string{"a", "b"}) {
200			t.Fatalf("Aliases returned shared slice: %v", got)
201		}
202		if n.Name() != "n" || n.Description() != "desc" {
203			t.Fatalf("accessors returned %q, %q", n.Name(), n.Description())
