222	func buildTree(t *testing.T, leafCall, aliasCall *call) *Node {
223		t.Helper()
224		root := New("tool", "root command", nil, noop)
225		remote := New("remote", "manage remotes", []string{"r"}, nil)
226		if err := root.Add(remote); err != nil {
227			t.Fatal(err)
228		}
229		if err := remote.Add(New("add", "add remote", []string{"a"}, recordingHandler(aliasCall))); err != nil {
230			t.Fatal(err)
231		}
232		serve := New("serve", "serve over http", []string{"srv", "go"}, recordingHandler(leafCall))
233		if err := root.Add(serve); err != nil {
234			t.Fatal(err)
235		}
236		leaf := New("status", "show status", nil, recordingHandler(leafCall))
237		if err := root.Add(leaf); err != nil {
238			t.Fatal(err)
239		}
240		return root
241	}
