291	func TestExactAndCaseSensitiveOnly(t *testing.T) {
292		var got call
293		root := buildTree(t, &got, nil)
294	
295		// Prefixes must not match.
296		err := root.Execute(context.Background(), []string{"ser"}, io.Discard, io.Discard)
297		if !errors.Is(err, ErrUnknownCommand) {
