345	func TestArgsExhausted(t *testing.T) {
346		// Parent without handler and children present.
347		root := New("tool", "", nil, nil)
348		remote := New("remote", "", nil, nil)
349		if err := root.Add(remote); err != nil {
350			t.Fatal(err)
351		}
352		if err := remote.Add(New("add", "", nil, noop)); err != nil {
353			t.Fatal(err)
354		}
355		err := root.Execute(context.Background(), nil, io.Discard, io.Discard)
356		if !errors.Is(err, ErrCommandRequired) {
357			t.Fatalf("root no args: error = %v, want ErrCommandRequired", err)
358		}
359		err = root.Execute(context.Background(), []string{"remote"}, io.Discard, io.Discard)
360		if !errors.Is(err, ErrCommandRequired) {
361			t.Fatalf("branch no args: error = %v, want ErrCommandRequired", err)
362		}
363	
364		// Handler present: called even with zero remaining arguments.
365		var got call
366		h := New("h", "", nil, recordingHandler(&got))
367		if err := h.Execute(context.Background(), nil, io.Discard, io.Discard); err != nil {
368			t.Fatal(err)
369		}
370		if want := []string{"h"}; !reflect.DeepEqual(got.path, want) {
371			t.Fatalf("path = %v, want %v", got.path, want)
372		}
373		if len(got.args) != 0 {
374			t.Fatalf("args = %v, want empty", got.args)
375		}
376	
377		// Branch node carrying both children and a handler: no args runs it.
378		var rootCall call
379		r2 := New("r2", "", nil, recordingHandler(&rootCall))
380		if err := r2.Add(New("child", "", nil, noop)); err != nil {
381			t.Fatal(err)
382		}
383		if err := r2.Execute(context.Background(), nil, io.Discard, io.Discard); err != nil {
384			t.Fatalf("branch with handler, no args: %v", err)
385		}
386		if want := []string{"r2"}; !reflect.DeepEqual(rootCall.path, want) || len(rootCall.args) != 0 {
387			t.Fatalf("branch handler got path %v args %v", rootCall.path, rootCall.args)
388		}
