416	func TestContextCanceledBeforeParse(t *testing.T) {
417		called := false
418		n := New("n", "", nil, func(path []string, args []string, stdout, stderr io.Writer) error {
419			called = true
420			return nil
421		})
422		ctx, cancel := context.WithCancel(context.Background())
423		cancel()
424		if err := n.Execute(ctx, nil, io.Discard, io.Discard); !errors.Is(err, context.Canceled) {
425			t.Fatalf("canceled ctx: error = %v, want context.Canceled", err)
426		}
427		ctx2, c2 := context.WithDeadline(context.Background(), time.Unix(1, 0))
428		defer c2()
429		if err := n.Execute(ctx2, nil, io.Discard, io.Discard); !errors.Is(err, context.DeadlineExceeded) {
430			t.Fatalf("expired ctx: error = %v, want context.DeadlineExceeded", err)
431		}
432		if called {
433			t.Fatal("handler must not run for a pre-canceled context")
434		}
435	}
