437	func TestDeeplyNestedTree(t *testing.T) {
438		var got call
439		depth := 8
440		root := New("lvl0", "", nil, nil)
441		cur := root
442		for i := 1; i < depth; i++ {
443			next := New("lvl"+digit(i), "", []string{"a" + digit(i)}, nil)
444			if err := cur.Add(next); err != nil {
445				t.Fatal(err)
446			}
447			cur = next
448		}
449		cur.handler = recordingHandler(&got)
450	
451		argv := []string{"a1", "lvl2", "a3", "lvl4", "a5", "lvl6", "a7", "tail1", "tail2"}
452		if err := root.Execute(context.Background(), argv, io.Discard, io.Discard); err != nil {
453			t.Fatal(err)
454		}
455		var wantPath []string
456		for i := 0; i < depth; i++ {
457			wantPath = append(wantPath, "lvl"+digit(i))
458		}
459		if !reflect.DeepEqual(got.path, wantPath) {
460			t.Fatalf("path = %v, want %v", got.path, wantPath)
461		}
462		if want := []string{"tail1", "tail2"}; !reflect.DeepEqual(got.args, want) {
463			t.Fatalf("args = %v, want %v", got.args, want)
464		}
465	}
466	
467	func digit(i int) string {
468		return string(rune('0' + i))
469	}
