1	// Package command implements a reusable command tree with arbitrary-depth
2	// subcommands and aliases.
3	//
4	// Nodes are created with New and attached to their parent with (*Node).Add.
5	// Execution starts at any node through (*Node).Execute, which descends one
6	// argument at a time, matching only exact, case-sensitive primary names and
7	// aliases; aliases resolve to the canonical primary name reported to the
8	// handler. The package never generates help text, completions, or log
9	// output, and it never writes to the stdout/stderr writers passed to
10	// Execute — only node handlers do.
11	package command
12	
13	import (
14		"context"
15		"errors"
16		"fmt"
17		"io"
18		"strings"
19	)
20	
21	// Sentinel errors describing registration and execution failures.
22	//
23	// Callers must use errors.Is rather than direct comparison where the
24	// documentation promises a wrapping error type (ErrInvalidName and
25	// ErrUnknownCommand); the others are returned directly.
26	var (
27		// ErrInvalidName indicates an empty or otherwise illegal primary name
28		// or alias. It is wrapped by *NameError carrying the offending name.
29		ErrInvalidName = errors.New("command: invalid command name")
30	
31		// ErrInvalidCommand is returned when Add receives a nil node (or a node
32		// that cannot legally be attached, such as an ancestor of the parent).
33		ErrInvalidCommand = errors.New("command: invalid command node")
34	
35		// ErrNameConflict indicates a duplicated primary name or alias under
36		// the same parent, including aliases duplicated inside one node. It is
37		// wrapped by *ConflictError carrying the duplicated name.
38		ErrNameConflict = errors.New("command: command name conflict")
39	
40		// ErrAlreadyAttached indicates that Add was called for a node that
41		// already has a parent. It is wrapped by *AttachedError.
42		ErrAlreadyAttached = errors.New("command: command already attached to a parent")
43	
44		// ErrUnknownCommand marks a LookupError produced when an argument
45		// matches neither a child's primary name nor one of its aliases.
46		ErrUnknownCommand = errors.New("command: unknown command")
47	
48		// ErrCommandRequired is returned when arguments run out at a node that
49		// has no handler, so no action can run.
50		ErrCommandRequired = errors.New("command: command required but no argument remained")
51	)
52	
53	// NameError wraps ErrInvalidName and reports the offending primary name or
54	// alias.
55	type NameError struct {
56		// Name is the primary name or alias that failed validation.
57		Name string
58	}
59	
60	func (e *NameError) Error() string {
61		return fmt.Sprintf("command: invalid command name %q", e.Name)
62	}
63	
64	// Unwrap exposes ErrInvalidName for errors.Is and errors.As.
65	func (e *NameError) Unwrap() error { return ErrInvalidName }
66	
67	// ConflictError wraps ErrNameConflict and reports the name that collided
68	// with an already registered primary name or alias.
69	type ConflictError struct {
70		// Name is the primary name or alias that collided.
71		Name string
72	}
73	
74	func (e *ConflictError) Error() string {
75		return fmt.Sprintf("command: command name %q is already registered", e.Name)
76	}
77	
78	// Unwrap exposes ErrNameConflict for errors.Is and errors.As.
79	func (e *ConflictError) Unwrap() error { return ErrNameConflict }
80	
81	// AttachedError wraps ErrAlreadyAttached and reports the node that was
82	// attached for a second time.
83	type AttachedError struct {
84		// Name is the primary name of the node that already has a parent.
85		Name string
86	}
87	
88	func (e *AttachedError) Error() string {
89		return fmt.Sprintf("command: command %q is already attached to a parent", e.Name)
90	}
91	
92	// Unwrap exposes ErrAlreadyAttached for errors.Is and errors.As.
93	func (e *AttachedError) Unwrap() error { return ErrAlreadyAttached }
94	
95	// LookupError wraps ErrUnknownCommand. It is returned when a node with
96	// children is asked to resolve an argument that matches none of them. The
97	// handler is not invoked and nothing is written to the Execute writers.
98	type LookupError struct {
99		// Path holds the canonical primary names resolved before the failure,
100		// starting with the execution root.
101		Path []string
102		// Arg is the argument that could not be resolved.
103		Arg string
104	}
105	
106	func (e *LookupError) Error() string {
107		if len(e.Path) == 0 {
108			return fmt.Sprintf("command: unknown command %q", e.Arg)
109		}
110		return fmt.Sprintf("command: unknown command %q for %q", e.Arg, strings.Join(e.Path, " "))
111	}
112	
113	// Unwrap exposes ErrUnknownCommand for errors.Is and errors.As.
114	func (e *LookupError) Unwrap() error { return ErrUnknownCommand }
115	
116	// HandlerFunc is the action attached to a node.
117	//
118	// path holds the canonical primary names from the execution root to the
119	// matched node; an alias used during resolution is replaced by the child's
120	// primary name. args holds the arguments not consumed by resolution, in
121	// their original order and with their original content. stdout and stderr
122	// are the writers passed to Execute. Whatever error the handler returns is
123	// returned by Execute without wrapping.
124	type HandlerFunc func(path []string, args []string, stdout, stderr io.Writer) error
125	
126	// Node is one command in the tree, identified by a primary name and zero or
127	// more aliases. A node may carry a handler, children, or both.
128	type Node struct {
129		name     string
130		desc     string
131		aliases  []string
132		handler  HandlerFunc
133		parent   *Node
134		children []*Node
135		byName   map[string]*Node
136	}
137	
138	// New creates an unattached node. handler may be nil; the aliases slice is
139	// copied so later caller mutations cannot affect the node. A node is not
140	// validated until it is attached with Add.
141	func New(name, description string, aliases []string, handler HandlerFunc) *Node {
142		return &Node{
143			name:    name,
144			desc:    description,
145			aliases: append([]string(nil), aliases...),
146			handler: handler,
147			byName:  make(map[string]*Node),
148		}
149	}
150	
151	// Name returns the node's primary name.
152	func (n *Node) Name() string { return n.name }
153	
154	// Description returns the node's description.
155	func (n *Node) Description() string { return n.desc }
156	
157	// Aliases returns a copy of the node's aliases in registration order.
158	func (n *Node) Aliases() []string { return append([]string(nil), n.aliases...) }
159	
160	// validName reports whether s is a legal primary name or alias: non-empty,
161	// restricted to ASCII letters, digits, hyphens and underscores, and not
162	// starting with a hyphen.
163	func validName(s string) bool {
164		if s == "" || s[0] == '-' {
165			return false
166		}
167		for i := 0; i < len(s); i++ {
168			switch c := s[i]; {
169			case c >= 'a' && c <= 'z':
170			case c >= 'A' && c <= 'Z':
171			case c >= '0' && c <= '9':
172			case c == '-' || c == '_':
173			default:
174				return false
175			}
176		}
177		return true
178	}
179	
180	// validateOwnNames checks the primary name and aliases of an unattached
181	// candidate node: every name must be valid, and no name may repeat.
182	func validateOwnNames(child *Node) error {
183		if !validName(child.name) {
184			return &NameError{Name: child.name}
185		}
186		seen := make(map[string]struct{}, len(child.aliases)+1)
187		seen[child.name] = struct{}{}
188		for _, alias := range child.aliases {
189			if !validName(alias) {
190				return &NameError{Name: alias}
191			}
192			if _, dup := seen[alias]; dup {
193				return &ConflictError{Name: alias}
194			}
195			seen[alias] = struct{}{}
196		}
197		return nil
198	}
199	
200	// Add attaches child to n. The tree is only modified after every check has
201	// succeeded, so a failed Add leaves the tree untouched. On success children
202	// remain in the order in which they were added.
203	func (n *Node) Add(child *Node) error {
204		if child == nil {
205			return ErrInvalidCommand
206		}
207		if err := validateOwnNames(child); err != nil {
208			return err
209		}
210		if child.parent != nil {
211			return &AttachedError{Name: child.name}
212		}
213		// Attaching an ancestor (including n itself) would create a cycle and
214		// corrupt traversal; treat it as an invalid node.
215		for ancestor := n; ancestor != nil; ancestor = ancestor.parent {
216			if ancestor == child {
217				return fmt.Errorf("command: cannot attach %q into its own subtree: %w", child.name, ErrInvalidCommand)
218			}
219		}
220		keys := make([]string, 0, len(child.aliases)+1)
221		keys = append(keys, child.name)
222		keys = append(keys, child.aliases...)
223		for _, key := range keys {
224			if _, exists := n.byName[key]; exists {
225				return &ConflictError{Name: key}
226			}
227		}
228	
229		for _, key := range keys {
230			n.byName[key] = child
231		}
232		n.children = append(n.children, child)
233		child.parent = n
234		return nil
235	}
236	
237	// Execute resolves args against the tree rooted at n and runs the matched
238	// handler. While the current node has children, the next argument selects a
239	// child by exact primary name or alias; a miss yields a *LookupError
240	// wrapping ErrUnknownCommand. Once a node without
241	// children is reached, all remaining arguments go to its handler. A node
242	// with children but no next argument runs its own handler when present and
243	// returns ErrCommandRequired otherwise.
244	//
245	// If ctx is already canceled or past its deadline before resolution starts,
246	// ctx.Err() is returned directly. Handler errors are returned unchanged and
247	// the package itself never writes to stdout or stderr.
248	func (n *Node) Execute(ctx context.Context, args []string, stdout, stderr io.Writer) error {
249		if err := ctx.Err(); err != nil {
250			return err
251		}
252	
253		current := n
254		path := []string{current.name}
255	
256		for len(current.children) > 0 {
257			if len(args) == 0 {
258				if current.handler != nil {
259					return current.handler(path, args, stdout, stderr)
260				}
261				return ErrCommandRequired
262			}
263			next, ok := current.byName[args[0]]
264			if !ok {
